            let closed;
            try {
              const parsed = JSON.parse(data);
              const repo = parsed.data.repository;
              if (repo) {
                closed = repo.pullRequest.closed;
              } else {
                console.warn(pr.branch,
                  "looks like a PR but isn't for a repo we manage so we assume",
                  'it is open');
