              console.info('Rate limited for', millis, 'milliseconds');
              setTimeout(() => resolve(closed), millis);
            } else {
              resolve(closed);
            }
          }
        });
      });
      req.on('error', err => {
        reject(`Error getting ${JSON.stringify(pr)}:\n${err}`);
      });
      req.write(postData);
      req.end();
    });
  }

  return {
    run: () => {
      return clone()
        .then(show_heads)
        .then(heads_to_prs)
        .then(cleanup_closed_prs);
    },
    clone: clone,
    is_pr_closed: is_pr_closed,

    repo: repo,
    local_path: local_path,
  };
