import os
import streamlit as st
import openai
from elasticsearch import Elasticsearch
from string import Template
import elasticapm
import time

from elasticsearch_llm_cache import (
    ElasticsearchLLMCache,  # Import the class from the file
)

## Configure OpenAI client
# openai.api_key = os.environ['OPENAI_API_KEY']
# openai.api_base = os.environ['OPENAI_API_BASE']
# openai.default_model = os.environ['OPENAI_API_ENGINE']
# openai.verify_ssl_certs = False

# Below is for Azure OpenAI
openai.api_type = os.environ["OPENAI_API_TYPE"]
openai.api_base = os.environ["OPENAI_API_BASE"]
openai.api_version = os.environ["OPENAI_API_VERSION"]
openai.verify_ssl_certs = False
engine = os.environ["OPENAI_API_ENGINE"]


# Configure APM and Elasticsearch clients
@st.cache_resource
def initElastic():
    # os.environ['ELASTIC_APM_SERVICE_NAME'] = "elasticsearch_llm_cache_demo"
    apmclient = elasticapm.Client()
    elasticapm.instrument()

    es = Elasticsearch(
        cloud_id=os.environ["ELASTIC_CLOUD_ID"].strip("="),
        basic_auth=(os.environ["ELASTIC_USER"], os.environ["ELASTIC_PASSWORD"]),
        request_timeout=30,
    )

    return apmclient, es


apmclient, es = initElastic()

# Set our data index
index = os.environ["ELASTIC_INDEX_DOCS"]


# Run an Elasticsearch query using hybrid RRF scoring of KNN and BM25
@elasticapm.capture_span("knn_search")
def search_knn(query_text, es):
    query = {
        "bool": {
            "must": [{"match": {"body_content": {"query": query_text}}}],
            "filter": [{"term": {"url_path_dir3": "elasticsearch"}}],
        }
    }

    knn = [
        {
            "field": "chunk-vector",
            "k": 10,
            "num_candidates": 10,
            "filter": {
                "bool": {
                    "filter": [
                        {"range": {"chunklength": {"gte": 0}}},
                        {"term": {"url_path_dir3": "elasticsearch"}},
                    ]
                }
            },
            "query_vector_builder": {
                "text_embedding": {
                    "model_id": "sentence-transformers__msmarco-minilm-l-12-v3",
                    "model_text": query_text,
                }
            },
        }
    ]

    rank = {"rrf": {}}

    fields = ["title", "url", "position", "url_path_dir3", "body_content"]

    resp = es.search(
        index=index,
        query=query,
        knn=knn,
        rank=rank,
        fields=fields,
        size=10,
        source=False,
    )

    body = resp["hits"]["hits"][0]["fields"]["body_content"][0]
    url = resp["hits"]["hits"][0]["fields"]["url"][0]

    return body, url


def truncate_text(text, max_tokens):
    tokens = text.split()
    if len(tokens) <= max_tokens:
        return text

    return " ".join(tokens[:max_tokens])


# Generate a response from ChatGPT based on the given prompt
def genAI(
    prompt,
    model="gpt-3.5-turbo",
    max_tokens=1024,
    max_context_tokens=4000,
    safety_margin=5,
    sys_content=None,
):

    # Truncate the prompt content to fit within the model's context length
    truncated_prompt = truncate_text(
        prompt, max_context_tokens - max_tokens - safety_margin
    )

    response = openai.ChatCompletion.create(
        engine=engine,
        temperature=0,
        messages=[
            {"role": "system", "content": sys_content},
            {"role": "user", "content": truncated_prompt},
        ],
    )

    # APM: add metadata labels of data we want to capture
    elasticapm.label(model=model)
    elasticapm.label(prompt=prompt)
    elasticapm.label(total_tokens=response["usage"]["total_tokens"])
    elasticapm.label(prompt_tokens=response["usage"]["prompt_tokens"])
    elasticapm.label(response_tokens=response["usage"]["completion_tokens"])
    if "USER_HASH" in os.environ:
        elasticapm.label(user=os.environ["USER_HASH"])

    return response["choices"][0]["message"]["content"]


def toLLM(resp, url, usr_prompt, sys_prompt, neg_resp, show_prompt, engine):
    prompt_template = Template(usr_prompt)
    prompt_formatted = prompt_template.substitute(
        query=query, resp=resp, negResponse=negResponse
    )
    answer = genAI(prompt_formatted, engine, sys_content=sys_prompt)

    # Display response from LLM
    st.header("Response from LLM")
    st.markdown(answer.strip())

    # We don't need to return a reference URL if it wasn't useful
    if not negResponse in answer:
        st.write(url)

    # Display full prompt if checkbox was selected
    if show_prompt:
        st.divider()
        st.subheader("Full prompt sent to LLM")
        prompt_formatted

    return answer


@elasticapm.capture_span("cache_search")
def cache_query(cache, prompt_text):
    return cache.query(prompt_text=query)


@elasticapm.capture_span("add_to_cache")
def add_to_cache(cache, prompt, response):
    return cache.add(prompt=prompt, response=response)


# sidebar setup
st.sidebar.header("Elasticsearch LLM Cache Info")

### MAIN

# Init Elastics

import { ElasticVectorSearch } from "@langchain/community/vectorstores/elasticsearch";
import { OpenAIEmbeddings } from "@langchain/openai";
import { Client } from "@elastic/elasticsearch";
import { readFile } from "node:fs/promises";
import dotenv from "dotenv";

dotenv.config();

const VECTOR_INDEX = "legal-precedents";

// Types
export interface DocumentMetadata {
  caseId: string;
  contractType: string;
  delayPeriod: string;
  outcome: string;
  reasoning: string;
  keyTerms: string;
  title: string;
}

export interface Document {
  pageContent: string;
  metadata: DocumentMetadata;
}

interface RawDocument {
  pageContent?: string;
  text?: string;
  metadata?: DocumentMetadata;
}

const esClient = new Client({
  node: process.env.ELASTICSEARCH_ENDPOINT!,
  auth: {
    apiKey: process.env.ELASTICSEARCH_API_KEY!,
  },
});

const embeddings = new OpenAIEmbeddings({
  model: "text-embedding-3-small",
});

const vectorStore = new ElasticVectorSearch(embeddings, {
  client: esClient,
  indexName: VECTOR_INDEX,
});

/**
 * Load dataset from a JSON file
 * @param path - Path to the JSON file
 * @returns Array of documents with pageContent and metadata
 */
export async function loadDataset(path: string): Promise<Document[]> {
  const raw = await readFile(path, "utf-8");
  const data: RawDocument[] = JSON.parse(raw);

  return data.map((d) => ({
    pageContent: String(d.pageContent ?? d.text ?? ""),
    metadata: (d.metadata ?? {}) as DocumentMetadata,
  }));
}

/**
 * Ingest data into Elasticsearch vector store
 * Creates the index if it doesn't exist and loads initial dataset
 */
export async function ingestData(): Promise<void> {
  const vectorExists = await esClient.indices.exists({ index: VECTOR_INDEX });

  if (!vectorExists) {
    console.log("CREATING VECTOR INDEX...");

    await esClient.indices.create({
      index: VECTOR_INDEX,
      mappings: {
        properties: {
          text: { type: "text" },
          embedding: {
            type: "dense_vector",
            dims: 1536,
            index: true,
            similarity: "cosine",
          },
          metadata: {
            type: "object",
            properties: {
              caseId: { type: "keyword" },
              contractType: { type: "keyword" },
              delayPeriod: {
                type: "text",
                fields: {
                  keyword: { type: "keyword" },
                },
              },
              outcome: { type: "keyword" },
              reasoning: { type: "text" },
              keyTerms: { type: "text" },
              title: {
                type: "text",
                fields: {
                  keyword: { type: "keyword" },
                },
              },
            },
          },
        },
      },
    });
  }

  const indexExists = await esClient.indices.exists({ index: VECTOR_INDEX });

  if (indexExists) {
    const indexCount = await esClient.count({ index: VECTOR_INDEX });
    const documentCount = indexCount.count;

    // Only ingest if index is empty
    if (documentCount > 0) {
      console.log(
        `Index already contains ${documentCount} documents. Skipping ingestion.`
      );
      return;
    }

    console.log("INGESTING DATASET...");
    const datasetPath = "./dataset.json";
    const initialDocs = await loadDataset(datasetPath).catch(() => []);

    await vectorStore.addDocuments(initialDocs);
    console.log(`✅ Successfully ingested ${initialDocs.length} documents`);
  }
}

export { VECTOR_INDEX };

