Instead of sending thousands of raw documents to an LLM, use aggregations to create concise summaries:

POST /customer-feedback/_search
{
  "size": 0,
  "aggs": {
    "sentiment_distribution": {
      "terms": {
        "field": "sentiment",
        "size": 10
      }
    },
    "avg_rating": {
      "avg": {
        "field": "rating"
      }
    },
    "top_issues": {
      "terms": {
        "field": "issue_category",
        "size": 5
      },
      "aggs": {
        "avg_severity": {
          "avg": {
            "field": "severity_score"
          }
        }
      }
