                    "query": term,
                    "fields": ["name", "category", "description"],
                }
            }
        ]
    )

    filters = []
    if categories:
        filters.append({"terms": {"category": categories}})
    if product_types:
        filters.append({"terms": {"product_type": product_types}})
    if brands:
        filters.append({"terms": {"brand.keyword": brands}})

    return {
